"""Fictional generated bytes only; these tests do not certify PPT/video content."""
import tempfile
import threading
import unittest
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen
from unittest.mock import patch

from workbench.attachments import ChatAttachments
from workbench.chat_delivery import ChatDeliveries
from workbench.chats import Chats
from workbench.config import Config, WorkbenchError
from workbench.delivery_policy import attachment_text, collect_outputs, output_snapshot
from workbench.ingress import DesktopIngress, IngressServer
from workbench.storage import Store


class ChatDeliveryTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='fictional-delivery-')
        self.root = Path(self.temp.name)
        self.chats = Chats(Store(Config(self.root / 'store', 'fictional-delivery')))
        for name in ('fictional-a', 'fictional-b'):
            self.chats.create({'id': name})
        self.chats.submit('fictional-a', {'id': 'fictional-turn', 'content': '制作虚构成品'})
        self.work = self.root / 'workspace'
        self.output = self.work / 'output'
        self.output.mkdir(parents=True)

    def tearDown(self):
        self.temp.cleanup()

    def make(self, name, content=b'EXPLICITLY FICTIONAL ARTIFACT BYTES 7319'):
        path = self.output / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
        return path

    def test_path_only_answer_becomes_durable_multiple_file_cards_and_survives_restart_backup(self):
        before = output_snapshot(self.output)
        paths = [self.make('fictional.pptx'), self.make('nested/fictional-anything.custom'), self.make('fictional empty.txt', b'')]
        answer = f'已生成虚构文件：`{paths[0]}`'
        selected = collect_outputs(answer, self.output, before, self.work)
        self.assertEqual(set(selected), set(paths))
        outputs = ChatDeliveries(self.chats).stage('fictional-turn', selected)
        self.assertEqual(len(outputs), 3)
        self.assertEqual(len(ChatDeliveries(self.chats).stage('fictional-turn', selected)), 3)
        self.chats.finish('fictional-turn', 'completed', attachment_text(answer, selected, self.work))
        paths[0].write_bytes(b'CHANGED FICTIONAL WORKING FILE')
        fresh = Chats(Store(self.chats.store.config))
        turn = fresh.read('fictional-a')['turns'][0]
        self.assertEqual(turn['outputs'], outputs)
        self.assertNotIn(str(self.work), turn['answer'])
        files = ChatAttachments(fresh)
        self.assertEqual(files.content('fictional-a', outputs[0]['id'])[1].read_bytes(), b'EXPLICITLY FICTIONAL ARTIFACT BYTES 7319')
        self.assertEqual(fresh.read('fictional-b')['turns'], [])
        with self.assertRaises(WorkbenchError):
            files.content('fictional-b', outputs[0]['id'])
        with patch('hashlib.sha256', side_effect=AssertionError('never rehash saved originals')):
            files.content('fictional-a', outputs[0]['id'])
        backup = self.chats.store.backup()
        dest = self.root / 'restored'
        Store.restore(self.chats.store.root / 'backups' / backup['backup_id'], dest)
        restored = Chats(Store(Config(dest, 'fictional-delivery')))
        self.assertEqual(restored.turn('fictional-turn')['outputs'], outputs)
        self.assertTrue(ChatAttachments(restored).content('fictional-a', outputs[0]['id'])[1].is_file())
        done = [e for e in fresh.events('fictional-a', 0) if e['kind'] == 'done'][0]
        self.assertEqual(done['payload']['outputs'], outputs)

    def test_only_changed_output_files_are_automatic_but_explicit_resends_work(self):
        old = self.make('old-fictional.txt')
        before = output_snapshot(self.output)
        self.assertEqual(collect_outputs('纯文字虚构解释，没有制作文件。', self.output, before, self.work), [])
        self.assertEqual(collect_outputs(f'MEDIA:"{old}"', self.output, before, self.work), [old])
        fresh = self.make('nested/new-fictional.bin')
        self.assertEqual(collect_outputs('虚构新成品已生成。', self.output, before, self.work), [fresh])
        self.assertEqual(collect_outputs('[官方资料](https://fictional.invalid/source.pdf)', self.output, output_snapshot(self.output), self.work), [])
        with self.assertRaisesRegex(ValueError, '下载地址'):
            collect_outputs('[下载成品](https://fictional.invalid/result.pptx)', self.output, output_snapshot(self.output), self.work)
        with self.assertRaisesRegex(ValueError, '下载地址'):
            collect_outputs('PPT已经生成：https://fictional.invalid/result.pptx', self.output, output_snapshot(self.output), self.work)
        with self.assertRaisesRegex(ValueError, '不存在'):
            collect_outputs('MEDIA:"output/missing-fictional.mp4"', self.output, before, self.work)
        self.assertEqual(collect_outputs('```\nMEDIA:/fictional/example.txt\n```', self.output, output_snapshot(self.output), self.work), [])

    def test_cancellation_during_copy_never_publishes_an_attachment(self):
        path = self.make('fictional.txt')
        original_copy = __import__('shutil').copyfileobj
        def cancel(incoming, outgoing, length):
            original_copy(incoming, outgoing, length)
            self.chats.cancel('fictional-a')
        with patch('workbench.chat_delivery.shutil.copyfileobj', side_effect=cancel):
            with self.assertRaises(WorkbenchError):
                ChatDeliveries(self.chats).stage('fictional-turn', [path])
        self.assertEqual(self.chats.turn('fictional-turn')['outputs'], [])
        self.assertEqual(list((self.chats.store.root / 'originals/chat-attachments').rglob('fictional.txt')), [])

    def test_generated_file_is_downloadable_only_from_its_original_chat_over_real_http(self):
        content = b'EXPLICITLY FICTIONAL DOWNLOAD 7319'
        file = ChatDeliveries(self.chats).stage('fictional-turn', [self.make('fictional.mp4', content)])[0]
        server = IngressServer(('127.0.0.1', 0), DesktopIngress(self.chats.store), 'fictional-token')
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        try:
            base = f'http://127.0.0.1:{server.server_address[1]}'
            def request(chat):
                return urlopen(Request(base + f'/v1/chats/{chat}/attachments/{file["id"]}/content', headers={'Authorization': 'Bearer fictional-token'}))
            with request('fictional-a') as response:
                self.assertEqual(response.read(), content)
                self.assertIn('fictional.mp4', response.headers['Content-Disposition'])
            with self.assertRaises(HTTPError) as rejected:
                request('fictional-b')
            rejected.exception.close()
        finally:
            server.shutdown()
            server.server_close()
            thread.join(2)
